package com.alpharip.staffmod.RecordingStudio.command;
import com.alpharip.staffmod.RecordingStudio.capture.RecordingCaptureService;import com.alpharip.staffmod.RecordingStudio.capture.RecordingCaptureSettings;import com.alpharip.staffmod.RecordingStudio.core.RecordingProject;import com.alpharip.staffmod.RecordingStudio.core.RecordingStudioController;import com.alpharip.staffmod.RecordingStudio.integration.MinecraftFramebufferFrameWriter;import com.alpharip.staffmod.RecordingStudio.integration.RecordingStudioRuntime;
import net.minecraft.client.Minecraft;import net.minecraft.command.CommandBase;import net.minecraft.command.CommandException;import net.minecraft.command.ICommandSender;import net.minecraft.util.ChatComponentText;import java.io.File;import java.util.Collections;import java.util.List;
/** In-game entry point for the standalone Recording Studio prototype. */
public final class RecordingStudioCommand extends CommandBase {
 public String getCommandName(){return "recordingstudio";}public String getCommandUsage(ICommandSender sender){return "/recordingstudio";}
 public int getRequiredPermissionLevel(){return 0;}
 public void processCommand(ICommandSender sender,String[] args)throws CommandException{if(args!=null&&args.length>0&&!"open".equalsIgnoreCase(args[0])){sender.addChatMessage(new ChatComponentText("§6[Recording Studio] §fUsage: /recordingstudio"));return;}Minecraft mc=Minecraft.getMinecraft();if(mc==null||mc.theWorld==null||mc.thePlayer==null){sender.addChatMessage(new ChatComponentText("§6[Recording Studio] §fJoin a world before opening Recording Studio."));return;}try{File root=new File(mc.mcDataDir,"recordingstudio");RecordingProject project=new RecordingProject("Manual Recording");File output=new File(new File(root,"recordings"),project.getId()+"/frames");RecordingCaptureService capture=new RecordingCaptureService(new MinecraftFramebufferFrameWriter(mc),new RecordingCaptureSettings(),output);RecordingStudioController controller=new RecordingStudioController(project,capture,new File(root,"projects"));new RecordingStudioRuntime(controller).open(mc);}catch(RuntimeException failure){sender.addChatMessage(new ChatComponentText("§6[Recording Studio] §fCould not open: "+failure.getMessage()));}}
 public List<String> addTabCompletionOptions(ICommandSender sender,String[] args,net.minecraft.util.BlockPos pos){return args!=null&&args.length==1?Collections.singletonList("open"):Collections.<String>emptyList();}
}
